        public static string GenerateHTML(DbResult dr, ArrayList sportIDList, int leagueID, Hashtable sportList, string fdate)
        {
            StringBuilder _s = new StringBuilder();
            try
            {
                if (dr.ResultSet.Tables[0].Rows.Count == 0)
                {
                    string s = WebUtils.LoadTemplate("Settle/NoResult.htm");
                    TemplateHandler.Assign(ref s, "{fdate}", fdate);
                    return s;
                }
                foreach (int _sportID in sportIDList)
                {
                    DataRow[] rows = dr.ResultSet.Tables[0].Select("sporttype=" + _sportID.ToString());

                    if (rows.Length > 0) _s.Append(GenerateHTMLBySportID(rows, _sportID, leagueID, sportList[_sportID].ToString(), fdate) + "<br />");
                }
            }
            catch (Exception ex)
            {
                {
                    Sunplus.Accounting.Core.Extensions.LogExtensions.ExceptionHandler(ex);
                }
                Logs.Write(ex.Message);
                throw ex;
            }
            return _s.ToString();
        }

        public static string GenerateHTMLBySportID(DataRow[] rows, int sportID, int leagueID, string sportName, string fdate)
        {
            try
            {
                switch (sportID)
                {
                    case 1: // Soccer
                        return SoccerHTML(sportID, sportName, rows, fdate);
                    case 2: // basketball
                    case 3: // football
                    case 26: // rugby
                    case 32: // netball
                        return BasketballHTML(sportID, sportName, rows, fdate);
                    case 4: //ice hockey
                    case 28: // field hockey
                        return HockeyHTML(sportID, sportName, rows, fdate);
                    case 5: // tennis
                        return TennisHTML(sportID, sportName, rows, fdate);
                    case 10: // golf
                    case 11: // Motorsports
                    case 7: // billiard
                    case 29://Winter Sports
                    case 33://     Cycling
                    case 34://     Fencing
                    case 35://     Judo
                    case 36://     Modern Pentathlon
                    case 37://     Rowing
                    case 38://     Sailing
                    case 39://     Shooting
                    case 40://     Taekwondo
                    case 41://     Triathlon
                    case 42://     Wrestling
                        return BilliardHTML(sportID, sportName, rows, fdate);
                    case 8: // baseball
                        return BaseBallHTML(sportID, sportName, rows, fdate);
                    case 9: // badminton
                    case 6: // volleyball
                    case 30: //Squash
                        return BadmintonHTML(sportID, sportName, rows, fdate);

                    #region Phuong.Nguyen@Updated <2008-12-25>, generate result for DARTS sport type

                    case 25:
                        return DartsHTML(sportID, sportName, rows, fdate);

                    #endregion Phuong.Nguyen@Updated <2008-12-25>, generate result for DARTS sport type

                    //Phuong.Nguyen, hide the FI result
                    case 201:
                        break;

                    case 151: //Horse Racing
                    case 152:
                    case 153:
                        return HorseRacingHTML(sportID, sportName, rows, fdate);
                    case 161: //Horse Racing
                        return NumberGameHTML(sportName, leagueID, fdate);
                    default: return CommonSportType(sportID, sportName, rows, fdate);
                }
            }
            catch (Exception ex)
            {
                {
                    Sunplus.Accounting.Core.Extensions.LogExtensions.ExceptionHandler(ex);
                }

                Logs.Write(ex.Message);
                throw ex;
            }
            return string.Empty;
        }

        //Phuong.Nguyen <2008-12-25>, genenate HTML result for DARTS sport type
        public static string DartsHTML(int sportID, string sportName, DataRow[] rows, string fdate)
        {
            string _sMain = WebUtils.LoadTemplate("Settle/ResultDarts.htm");
            string _strRow = WebUtils.LoadTemplate("Settle/ResultDartsRow.htm");
            string _strLeague = TemplateHandler.CopyBlock(_sMain, "leaguename");
            TemplateHandler.RemoveBlock(ref _sMain, "leaguename");
            TemplateHandler.ReplaceBlock(ref _strLeague, "btnRef", "&nbsp;");
            string curLeagueId = "";
            string bgClass = " rowEven";
            StringBuilder _s = new StringBuilder(); // content
            //------------
            foreach (DataRow dr in rows)
            {
                bgClass = (bgClass == " rowEven") ? string.Empty : " rowEven";
                string _sRow = _strRow;
                string _leagueid = dr["leagueid"].ToString();
                if (!curLeagueId.Equals(_leagueid))
                {
                    curLeagueId = _leagueid;
                    string _sleague = _strLeague;
                    TemplateHandler.Assign(ref _sleague, "{leaguename}", CacheRef.GetLeagueName(dr["leagueid"]));
                    bgClass = string.Empty;
                    _s.Append(_sleague);
                }
                TemplateHandler.Assign(ref _sRow, "{bgClass}", bgClass);
                TemplateHandler.Assign(ref _sRow, "{code}", dr["matchcode"].ToString());
                TemplateHandler.Assign(ref _sRow, "{homeTeam}", CacheRef.GetTeamName(dr["homeid"]) + (CastAide.AsBoolean(dr["isNeutral"]) ? ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "IsNeutral") : string.Empty));
                TemplateHandler.Assign(ref _sRow, "{awayTeam}", CacheRef.GetTeamName(dr["awayid"]));
                bool _isCalculated = Convert.ToBoolean(dr["IsCalculated"]);
                bool _isMultiCaled = Convert.ToBoolean(dr["IsMultiCaled"]);
                bool _isRefund = Convert.ToBoolean(dr["IsRefund"]);
                bool _isCalRefund = Convert.ToBoolean(dr["IsCalRefund"]);

                string _time = string.Format(cult, "{0:MM/dd/yy hh:mm:ss tt}", dr["kickofftime"]);
                TemplateHandler.Assign(ref _sRow, "{date}", _time);
                TemplateHandler.Assign(ref _sRow, "{homeFT}", (!Convert.IsDBNull(dr["finalhomescore"])) ? CastAide.AsInt32(dr["finalhomescore"]).ToString() : "-");
                TemplateHandler.Assign(ref _sRow, "{awayFT}", (!Convert.IsDBNull(dr["finalawayscore"])) ? CastAide.AsInt32(dr["finalawayscore"]).ToString() : "-");
                string _eventstatus = dr["eventstatus"].ToString();
                TemplateHandler.Assign(ref _sRow, "{eventstatus}", GetStatusStr(_eventstatus));
                _s.Append(_sRow);
            }

            TemplateHandler.Assign(ref _sMain, "{fdate}", fdate);
            TemplateHandler.Assign(ref _sMain, "{content}", _s.ToString());
            TemplateHandler.Assign(ref _sMain, "{sportname}", sportName.ToUpperInvariant());
            return _sMain;
        }

