        private static void ResultWhenRefund(ref string homeHT, ref string awayHT, ref string homeFT, ref string awayFT, string status)
        {
            switch (status)
            {
                case "Refund HT":
                    homeHT = ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "lblNA");
                    awayHT = ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "lblNA");
                    break;

                case "Refund FT":
                    homeFT = ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "lblNA");
                    awayFT = ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "lblNA");
                    break;

                case "Refund":
                    homeHT = ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "lblNA");
                    awayHT = ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "lblNA");
                    homeFT = ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "lblNA");
                    awayFT = ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "lblNA");
                    break;
            }
        }

        public static string SoccerHTML(int sportID, string sportName, DataRow[] rows, string fdate)
        {
            try
            {
                string _sMain = WebUtils.LoadTemplate("Settle/ResultSoccer.htm");
                string _strRow = WebUtils.LoadTemplate("Settle/ResultRowSoccer.htm");
                string _strLeague = TemplateHandler.CopyBlock(_sMain, "leaguename");
                TemplateHandler.RemoveBlock(ref _sMain, "leaguename");
                TemplateHandler.ReplaceBlock(ref _strLeague, "btnRef", "&nbsp;");
                string curLeagueId = "";
                string bgClass = " rowEven";
                StringBuilder _s = new StringBuilder(); // content
                //------------
                foreach (DataRow dr in rows)
                {
                    bgClass = (bgClass == " rowEven") ? string.Empty : " rowEven";
                    string _sRow = _strRow;
                    string _leagueid = dr["leagueid"].ToString();
                    if (!curLeagueId.Equals(_leagueid))
                    {
                        curLeagueId = _leagueid;
                        string _sleague = _strLeague;
                        TemplateHandler.Assign(ref _sleague, "{leaguename}", CacheRef.GetLeagueName(dr["leagueid"]));
                        bgClass = string.Empty;
                        _s.Append(_sleague);
                    }
                    TemplateHandler.Assign(ref _sRow, "{bgClass}", bgClass);
                    TemplateHandler.Assign(ref _sRow, "{code}", dr["matchcode"].ToString());
                    TemplateHandler.Assign(ref _sRow, "{hometeam}", CacheRef.GetTeamName(dr["homeid"]) + (CastAide.AsBoolean(dr["isNeutral"]) ? ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "IsNeutral") : string.Empty));
                    TemplateHandler.Assign(ref _sRow, "{awayteam}", CacheRef.GetTeamName(dr["awayid"]));
                    string _time = string.Format(cult, "{0:MM/dd/yy hh:mm:ss tt}", dr["kickofftime"]);
                    TemplateHandler.Assign(ref _sRow, "{date}", _time);

                    string _eventstatus = dr["eventstatus"].ToString();
                    string homeHT = (!Convert.IsDBNull(dr["hthomescore"])) ? CastAide.AsInt32(dr["hthomescore"]).ToString() : "-";
                    string homeFT = (!Convert.IsDBNull(dr["finalhomescore"])) ? CastAide.AsInt32(dr["finalhomescore"]).ToString() : "-";
                    string awayHT = (!Convert.IsDBNull(dr["htawayscore"])) ? CastAide.AsInt32(dr["htawayscore"]).ToString() : "-";
                    string awayFT = (!Convert.IsDBNull(dr["finalawayscore"])) ? CastAide.AsInt32(dr["finalawayscore"]).ToString() : "-";

                    ResultWhenRefund(ref homeHT, ref awayHT, ref homeFT, ref  awayFT, _eventstatus);

                    TemplateHandler.Assign(ref _sRow, "{homeHT}", homeHT);
                    TemplateHandler.Assign(ref _sRow, "{homeFT}", homeFT);
                    TemplateHandler.Assign(ref _sRow, "{awayHT}", awayHT);
                    TemplateHandler.Assign(ref _sRow, "{awayFT}", awayFT);

                    bool _isRefund = Convert.ToBoolean(dr["IsRefund"]);
                    bool _isCalRefund = Convert.ToBoolean(dr["IsCalRefund"]);
                    if (!_isCalRefund && !Convert.IsDBNull(dr["betstatus"]) && !string.IsNullOrEmpty(dr["betstatus"].ToString()) && !"0".Equals(CastAide.AsString(dr["betstatus"])))//phuong.nguyen@updated
                    {
                        string[] _betStatus = dr["betstatus"].ToString().Split(':');
                        if (_betStatus.Length >= 2 && _betStatus[1].Split('-').Length == 2)
                        {
                            string _fg = _betStatus[1].Split('-')[0];
                            string _lg = _betStatus[1].Split('-')[1];
                            if (_fg == "1") TemplateHandler.Assign(ref _sRow, "{fgHome}", "x");
                            if (_fg == "2") TemplateHandler.Assign(ref _sRow, "{fgAway}", "x");
                            if (_lg == "1") TemplateHandler.Assign(ref _sRow, "{lgHome}", "x");
                            if (_lg == "2") TemplateHandler.Assign(ref _sRow, "{lgAway}", "x");
                        }
                    }
                    TemplateHandler.Assign(ref _sRow, "{fgHome}", string.Empty);
                    TemplateHandler.Assign(ref _sRow, "{fgAway}", string.Empty);
                    TemplateHandler.Assign(ref _sRow, "{lgHome}", string.Empty);
                    TemplateHandler.Assign(ref _sRow, "{lgAway}", string.Empty);

                    string goalrecord = CastAide.AsString(dr["goalrecord"], "");
                    goalrecord = (_eventstatus.ToLower().IndexOf(Status.Refund.ToLower()) != -1) ? "" : goalrecord;
                    string hrefGoalHistory = "../Report/GoalHistory.aspx?leagueid=" + _leagueid + "&sporttype=" + sportID + "&homeid=" + dr["homeid"].ToString()
                                             + "&awayid=" + dr["awayid"].ToString() + "&goalrecord=" + goalrecord + "&isneutral=" + (CastAide.AsBoolean(dr["isNeutral"]) ? "True" : string.Empty);
                    string linkGoalHistory = (string.IsNullOrEmpty(goalrecord)) ? "" : GenerateHtml.GenLinkPopup("../", hrefGoalHistory, ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "lblGoalHistory"), 325, 100 + (15 * goalrecord.Length), 300, 105, "[" + "<span class='goalhistory'>i</span>" + "]");
                    TemplateHandler.Assign(ref _sRow, "goalhistory", linkGoalHistory);

                    //TemplateHandler.Assign(ref _sRow, "{eventstatus}", GetStatusStr(_eventstatus, new string[] { dr["ishtcal"].ToString(), dr["IsCalculated"].ToString() }));
                    //TemplateHandler.Assign(ref _sRow, "{bgEventStatus}", string.Empty);

                    var isPending = false;
                    var settle = CommonBootStrapper.Locator.GetInstance<ISettlement>();
                    TemplateHandler.Assign(ref _sRow, "{eventstatus}", settle.SelStatusConfirming(dr, ref isPending));
                    TemplateHandler.Assign(ref _sRow, "{bgEventStatus}", (string.Compare(_eventstatus, "postponed", true) == 0) ? SettleBgColor.POSTPONED :
                        (isPending ? SettleBgColor.PendingStatus : SettleBgColor.DEFAULTCOLOR));

                    _s.Append(_sRow);
                }

                TemplateHandler.Assign(ref _sMain, "{fdate}", fdate);
                TemplateHandler.Assign(ref _sMain, "{content}", _s.ToString());
                TemplateHandler.Assign(ref _sMain, "{sportname}", sportName.ToUpperInvariant());
                return _sMain;
            }
            catch
            {
                return string.Empty;
            }
        }

        public static string GetStatusStr(string _eventstatus, params string[] options)
        {
            switch (_eventstatus.ToLowerInvariant())
            {
                case "running":
                    {
                        if (options != null && options.Length == 2)
                        {
                            bool isHTcal = false;
                            bool calculate = false;
                            if (options[0].Length > 1)//false,true
                            {
                                isHTcal = DNAide.Core.CastAide.AsBoolean(options[0].ToLower().Trim());
                                calculate = DNAide.Core.CastAide.AsBoolean(options[1].ToLower().Trim());
                            }
                            else//0,1
                            {
                                isHTcal = DNAide.Core.CastAide.AsBoolean(Convert.ToInt16(options[0].Trim()));
                                calculate = DNAide.Core.CastAide.AsBoolean(Convert.ToInt16(options[1].Trim()));
                            }
                            if (isHTcal) //isHTcal
                                return ResourceExtension.GetResourceValue(ResourceExtension.Resources.CategorizeStatus, "FTPending");
                            else if (calculate) //calculate
                                return ResourceExtension.GetResourceValue(ResourceExtension.Resources.CategorizeStatus, "HTPending");
                            else
                                return ResourceExtension.GetResourceValue(ResourceExtension.Resources.CategorizeStatus, "Pending");
                        }
                        else
                        {
                            return "Pending";
                        }
                    }
                case "completed": return "Completed";
                case "closed": return "Closed";
                case "postponed": return "Postponed";
                case "internal": return "Internal";
                default: return _eventstatus;
            }
        }

        public static string BasketballHTML(int sportID, string sportName, DataRow[] rows, string fdate)
        {
            int totalSets = 4;
            string _sMain = WebUtils.LoadTemplate("Settle/ResultBasketball.htm");
            string _strRow = WebUtils.LoadTemplate("Settle/ResultRowBasketball.htm");
            string _strLeague = TemplateHandler.CopyBlock(_sMain, "leaguename");
            TemplateHandler.RemoveBlock(ref _sMain, "leaguename");
            TemplateHandler.ReplaceBlock(ref _strLeague, "btnRef", "&nbsp;");
            string curLeagueId = "";
            string bgClass = " rowEven";
            StringBuilder _s = new StringBuilder(); // content
            //------------
            foreach (DataRow dr in rows)
            {
                bgClass = (bgClass == " rowEven") ? string.Empty : " rowEven";
                string _sRow = _strRow;
                string _leagueid = dr["leagueid"].ToString();
                if (!curLeagueId.Equals(_leagueid))
                {
                    curLeagueId = _leagueid;
                    string _sleague = _strLeague;
                    TemplateHandler.Assign(ref _sleague, "{leaguename}", CacheRef.GetLeagueName(dr["leagueid"]));
                    bgClass = string.Empty;
                    _s.Append(_sleague);
                }
                TemplateHandler.Assign(ref _sRow, "{bgClass}", bgClass);
                TemplateHandler.Assign(ref _sRow, "{code}", dr["matchcode"].ToString());
                TemplateHandler.Assign(ref _sRow, "{homeTeam}", CacheRef.GetTeamName(dr["homeid"]) + (CastAide.AsBoolean(dr["isNeutral"]) ? ResourceExtension.GetResourceValue(ResourceExtension.Resources.Language, "IsNeutral") : string.Empty));
                TemplateHandler.Assign(ref _sRow, "{awayTeam}", CacheRef.GetTeamName(dr["awayid"]));
                bool _isCalculated = Convert.ToBoolean(dr["IsCalculated"]);
                bool _isMultiCaled = Convert.ToBoolean(dr["IsMultiCaled"]);
                bool _isRefund = Convert.ToBoolean(dr["IsRefund"]);
                bool _isCalRefund = Convert.ToBoolean(dr["IsCalRefund"]);
                int i = 0;
                string _homeOT = "-", _awayOT = "-";
                if (!_isCalRefund && !Convert.IsDBNull(dr["betstatus"]) && !string.IsNullOrEmpty(dr["betstatus"].ToString()) && !"0".Equals(CastAide.AsString(dr["betstatus"])))
                {
                    string[] _betStatus;

                    if (dr["betstatus"].ToString().IndexOf(';') > -1)
                    {
                        _betStatus = dr["betstatus"].ToString().Split(';')[1].Split(',');
                    }
                    else
                    {
                        _betStatus = dr["betstatus"].ToString().Split(',');
                    }
                    for (; i < _betStatus.Length; i++)
                    {
                        var h_a = _betStatus[i].Trim().Split('-');
                        string _cHome = h_a.Length > 0 ? h_a[0] : string.Empty;
                        string _cAway = h_a.Length > 1 ? h_a[1] : string.Empty;
                        TemplateHandler.Assign(ref _sRow, "{home" + (i + 1).ToString() + "Q}", _cHome);
                        TemplateHandler.Assign(ref _sRow, "{away" + (i + 1).ToString() + "Q}", _cAway);
                        if (i == totalSets)
                        {
                            _homeOT = _cHome;
                            _awayOT = _cAway;
                        }
                    }
                    i--;
                }
                for (; i < totalSets; i++)
                {
                    TemplateHandler.Assign(ref _sRow, "{home" + (i + 1).ToString() + "Q}", "-");
                    TemplateHandler.Assign(ref _sRow, "{away" + (i + 1).ToString() + "Q}", "-");
                }

                TemplateHandler.Assign(ref _sRow, "{homeOT}", _homeOT);
                TemplateHandler.Assign(ref _sRow, "{awayOT}", _awayOT);
                string _time = string.Format(cult, "{0:MM/dd/yy hh:mm:ss tt}", dr["kickofftime"]);
                TemplateHandler.Assign(ref _sRow, "{date}", _time);
                TemplateHandler.Assign(ref _sRow, "{homeHT}", (!Convert.IsDBNull(dr["hthomescore"])) ? CastAide.AsInt32(dr["hthomescore"]).ToString() : "-");
                TemplateHandler.Assign(ref _sRow, "{awayHT}", (!Convert.IsDBNull(dr["htawayscore"])) ? CastAide.AsInt32(dr["htawayscore"]).ToString() : "-");
                TemplateHandler.Assign(ref _sRow, "{homeFT}", (!Convert.IsDBNull(dr["finalhomescore"])) ? CastAide.AsInt32(dr["finalhomescore"]).ToString() : "-");
                TemplateHandler.Assign(ref _sRow, "{awayFT}", (!Convert.IsDBNull(dr["finalawayscore"])) ? CastAide.AsInt32(dr["finalawayscore"]).ToString() : "-");
                string _eventstatus = dr["eventstatus"].ToString();
                //if (sportID != 32)
                //{
                //    TemplateHandler.Assign(ref _sRow, "{eventstatus}", GetStatusStr(_eventstatus, new string[] { dr["ishtcal"].ToString(), dr["IsCalculated"].ToString() }));
                //}
                //else
                //{
                //    TemplateHandler.Assign(ref _sRow, "{eventstatus}", GetStatusStr(_eventstatus));
                //}
                var isPending = false;
                var settle = CommonBootStrapper.Locator.GetInstance<ISettlement>();
                TemplateHandler.Assign(ref _sRow, "{eventstatus}", settle.SelStatusConfirming(dr, ref isPending));
                TemplateHandler.Assign(ref _sRow, "{bgEventStatus}", (string.Compare(_eventstatus, "postponed", true) == 0) ? SettleBgColor.POSTPONED :
                    (isPending ? SettleBgColor.PendingStatus : SettleBgColor.DEFAULTCOLOR));

                _s.Append(_sRow);
            }

            TemplateHandler.Assign(ref _sMain, "{fdate}", fdate);
            TemplateHandler.Assign(ref _sMain, "{content}", _s.ToString());
            TemplateHandler.Assign(ref _sMain, "{sportname}", sportName.ToUpperInvariant());
            return _sMain;
        }

