            try
            {
                DataTable dt = DataAccess.IBCDLL.Accounting.Settle.GetNumberGameResult(CastAide.AsDateTime(fdate), leagueID);

                string _sMain = WebUtils.LoadTemplate("Settle/ResultNumberGame.htm");
                string _strRow = WebUtils.LoadTemplate("Settle/ResultNumberGameRow.htm");
                string _strLeague = TemplateHandler.CopyBlock(_sMain, "leaguename");
                TemplateHandler.RemoveBlock(ref _sMain, "leaguename");

                StringBuilder _s = new StringBuilder(); // content

                List<int> leagueids = GetLeagues(dt);
                foreach (int _leagueid in leagueids)
                {
                    string _sleague = _strLeague;
                    TemplateHandler.Assign(ref _sleague, "{leaguename}", CacheRef.GetLeagueName(_leagueid));
                    _s.Append(_sleague);
                    List<string> matchids = GetMatchsByLeagueId(dt, _leagueid);
                    foreach (string _matchid in matchids)
                    {
                        string bgClass = "";
                        int totalUnder = 0;
                        int totalOver = 0;
                        int totalNumber = 0;
                        string resultNumber = "";
                        string FirstBall = "";
                        string LastBall = "";
                        var secondBall = 0;
                        var thirdBall = 0;
                        string Result = "";
                        string Warrior = "";
                        string OEFT = "";
                        string KickOffTime = "";
                        string LastLiveBall = "";
                        int totalseq = 0;
                        int number;
                        string imgnumber;
                        bgClass = (bgClass == " evenrow") ? string.Empty : " evenrow";
                        string _sRow = _strRow;

                        DataRow[] rows = GetSeqNumberByMatchId(dt, _matchid);
                        totalseq = rows.Length;
                        if (rows.Length > 0)
                        {
                            KickOffTime = rows[0]["eventdate"].ToString();
                            FirstBall = "<img src='Images/" + (CastAide.AsInt16(rows[0]["number"], 0) < 10 ? "0" + rows[0]["number"].ToString() + ".jpg" : rows[0]["number"].ToString() + ".jpg") + "' border='0' hspace='1' vspace='1'>";
                            LastBall = "<img src='Images/" + (CastAide.AsInt16(rows[rows.Length - 1]["number"], 0) < 10 ? "0" + rows[rows.Length - 1]["number"].ToString() + ".jpg" : rows[rows.Length - 1]["number"].ToString() + ".jpg") + "' border='0' hspace='1' vspace='1'>";
                            if (rows.Length >= 2)
                            {
                                secondBall = CastAide.AsInt16(rows[1]["number"].ToString());
                            }
                            if (rows.Length >= 3)
                            {
                                thirdBall = CastAide.AsInt16(rows[2]["number"].ToString());
                            }
                            int i = 1;
                            string imgtd = "";
                            foreach (DataRow row in rows)
                            {
                                number = CastAide.AsInt16(row["number"], 0);
                                imgnumber = number < 10 ? "0" + number.ToString() + ".jpg" : number.ToString() + ".jpg";

                                if (number >= 38)
                                {
                                    totalOver++;
                                }
                                else
                                {
                                    totalUnder++;
                                }
                                if (i == 1)
                                {
                                    imgtd = "<tr><td><img src='Images/" + imgnumber + "' border='0' hspace='1' vspace='1'></td>";
                                    i++;
                                }
                                else if (i == 15)
                                {
                                    imgtd = "<td><img src='Images/" + imgnumber + "' border='0' hspace='1' vspace='1'></td></tr>";
                                    i = 1;
                                }
                                else
                                {
                                    imgtd = "<td><img src='Images/" + imgnumber + "' border='0' hspace='1' vspace='1'></td>";
                                    i++;
                                }

                                resultNumber += imgtd;

                                totalNumber += number;
                            }
                            if (i > 1 && i < 15)
                            {
                                for (int j = i; j < 14; j++)
                                {
                                    resultNumber += "<td></td>";
                                }
                                resultNumber += "</tr>";
                            }
                            Result = "<table class=\"noneborder\" cellspacing=\"0\">" + resultNumber + "</table>";

                            #region get last live ball

                            if (totalseq <= 30)
                                number = CastAide.AsInt16(dt.Rows[totalseq - 1]["number"], 0);
                            else
                                number = CastAide.AsInt16(dt.Rows[29]["number"], 0);

                            #endregion get last live ball

                            imgnumber = number < 10 ? "0" + number.ToString() + ".jpg" : number.ToString() + ".jpg";
                            LastLiveBall = "<img src='Images/" + imgnumber + "' border='0' >";

                            Warrior = secondBall > thirdBall ? "2nd ball Win" : "3rd ball Win";

                            OEFT = totalNumber % 2 == 0 ? "EVEN" : "ODD";
                        }
                        TemplateHandler.Assign(ref _sRow, "{KickOffTime}", KickOffTime);
                        TemplateHandler.Assign(ref _sRow, "{Match}", _matchid.ToString());
                        TemplateHandler.Assign(ref _sRow, "{Result}", Result);
                        TemplateHandler.Assign(ref _sRow, "{FirstBall}", FirstBall);
                        TemplateHandler.Assign(ref _sRow, "{LastBall}", LastBall);
                        TemplateHandler.Assign(ref _sRow, "{LastLiveBall}", LastLiveBall);
                        TemplateHandler.Assign(ref _sRow, "{Warrior}", Warrior);
                        TemplateHandler.Assign(ref _sRow, "{OEFT}", OEFT);
                        TemplateHandler.Assign(ref _sRow, "{Status}", "Completed");
                        _s.Append(_sRow);
                    }
                }

                TemplateHandler.Assign(ref _sMain, "{fdate}", fdate);
                TemplateHandler.Assign(ref _sMain, "{content}", _s.ToString());
                TemplateHandler.Assign(ref _sMain, "{sportname}", sportName.ToUpperInvariant());
                return _sMain;
            }
            catch
            {
                return string.Empty;
            }
        }

        private static void GetScratchAndTFHorses(DataRow[] rows, int leagueId, string raceName, ref string strSCR, ref string strTF)
        {
            strTF = "";
            strSCR = "";
            try
            {
                int rowNo = rows.Length;
                for (int index = 0; index < rowNo; index++)
                {
                    DataRow r = rows[index];
                    if (leagueId == CastAide.AsInt32(r["leagueid"], 0) &&
                        raceName.Equals(CastAide.AsString(r["matchid"], ""))
                        )
                    {
                        if (CastAide.AsInt32(r["htawayscore"], 0) == 1)
                            strSCR += CastAide.AsString(r["matchcode"]) + ", ";
                        if (CastAide.AsInt32(r["hthomescore"], 0) == 1)
                            strTF += CastAide.AsString(r["matchcode"]) + ", ";
                    }
                }

                strSCR = (!string.IsNullOrEmpty(strSCR)) ? strSCR.Substring(0, strSCR.LastIndexOf(",")).Trim() : "";
                strTF = (!string.IsNullOrEmpty(strTF)) ? strTF.Substring(0, strTF.LastIndexOf(",")).Trim() : "";
            }
            catch (Exception ex)
            {
                {
                    Sunplus.Accounting.Core.Extensions.LogExtensions.ExceptionHandler(ex);
                }
                strSCR = "";
                strTF = "";
            }
        }

        private static List<int> GetLeagues(DataTable tb)
        {
            return (from row in tb.AsEnumerable()
                    select row.Field<int>("leagueid")).Distinct().ToList();
        }

        private static List<string> GetMatchsByLeagueId(DataTable tb, int leagueId)
        {
            return (from row in tb.AsEnumerable()
                    where row.Field<int>("leagueid") == leagueId
                    select row.Field<string>("matchcode")).Distinct().ToList();
        }

        private static DataRow[] GetSeqNumberByMatchId(DataTable tb, string matchId)
        {
            DataRow[] rows = tb.Select("matchcode=" + matchId);
            return rows;
        }
    }
}